insert into public.flashcards (id, deck, domain, objective, front, back) values
('f2-056','core',2,'2.1',$$What distinguishes a "malicious insider" from a "negligent insider"?$$,$$Malicious: intentional harm (revenge/profit). Negligent: unintentional risk via carelessness (misconfig, phishing click, lost device) - both are insider threats but need different controls.$$),
('f2-057','core',2,'2.1',$$What is an Advanced Persistent Threat (APT)?$$,$$A well-resourced, patient threat actor (often nation-state) that establishes long-term, stealthy access for sustained espionage or disruption rather than a quick smash-and-grab.$$),
('f2-058','core',2,'2.1',$$How does attacker sophistication shape attack choice?$$,$$Higher resources/sophistication (nation-state) buy custom malware and zero-days plus patience; lower (script kiddie) rely on public tools and speed over stealth.$$),
('f2-059','core',2,'2.2',$$What is quishing?$$,$$Phishing via a malicious QR code leading to a credential-harvesting or malware site - exploits that a QR code's destination isn''t visible before scanning.$$),
('f2-060','core',2,'2.2',$$What is a BadUSB / HID-emulation attack?$$,$$A malicious USB device emulates a keyboard and injects keystrokes/commands the instant it is plugged in - no file needs to be opened, unlike simple USB baiting.$$),
('f2-061','core',2,'2.2',$$Pretext vs authority as social engineering elements?$$,$$Pretext: the fabricated story/scenario. Authority: the persuasion principle of impersonating someone whose instructions aren''t normally questioned (executive, IT, law enforcement).$$),
('f2-062','core',2,'2.2',$$What is malvertising?$$,$$Malicious code or an exploit hidden in an ad creative served through a legitimate ad network - infects visitors of otherwise trustworthy sites without compromising the site itself.$$),
('f2-063','core',2,'2.3',$$What is a default configuration vulnerability?$$,$$Shipped settings (default admin password, open management port, sample app) left unchanged after deployment - one of the most common, easily preventable weaknesses.$$),
('f2-064','core',2,'2.3',$$What is the "excessive data exposure" insecure-API vulnerability?$$,$$An API returns more data than the caller needs (e.g., a full profile including SSN for a name lookup) - a common flaw distinct from missing auth or injection.$$),
('f2-065','core',2,'2.3',$$Why are containers vulnerable to image supply-chain risk?$$,$$Base images pulled from public registries can carry known CVEs or planted malware; unscanned, unverified images inherit that risk into every container built from them.$$),
('f2-066','core',2,'2.3',$$What is a TOCTOU symlink attack?$$,$$An attacker swaps a file for a symlink to a sensitive target between a program''s permission check and its actual file access, redirecting the operation to an unintended file.$$),
('f2-067','core',2,'2.4',$$Polymorphic vs metamorphic malware?$$,$$Polymorphic: changes its encrypted/obfuscated wrapper each infection while the core payload logic stays the same (evades signatures). Metamorphic: rewrites its own code logic each time - harder to detect.$$),
('f2-068','core',2,'2.4',$$What is a bot and a botnet?$$,$$Bot: a single compromised, remotely controlled host. Botnet: a large network of bots under one attacker''s C2, used for DDoS, spam, or distributed cracking.$$),
('f2-069','core',2,'2.4',$$Credential harvesting vs credential stuffing?$$,$$Harvesting: collecting credentials (phishing pages, keyloggers, breaches). Stuffing: automated reuse of harvested/breached credentials against other services, banking on password reuse.$$),
('f2-070','core',2,'2.4',$$What is a pass-the-hash attack?$$,$$Reusing a captured password HASH directly to authenticate, without ever cracking it to plaintext - works against protocols that accept the hash itself as proof.$$),
('f2-071','core',2,'2.4',$$What is ARP spoofing mechanically?$$,$$Sending forged ARP replies claiming the attacker''s MAC address owns the gateway''s IP, so victims send their traffic to the attacker instead - the mechanism behind on-path attacks on a LAN.$$),
('f2-072','core',2,'2.4',$$What indicators suggest resource-consumption abuse (e.g., cryptomining malware)?$$,$$Sustained high CPU/GPU usage with no matching legitimate workload, elevated power/cooling costs, and unexplained fan noise/heat on affected hosts.$$),
('f2-073','core',2,'2.5',$$What is the principle behind time-based access restrictions as a mitigation?$$,$$Limiting when accounts/systems can authenticate (e.g., business hours only) shrinks the window an attacker using stolen credentials can act in.$$),
('f2-074','core',2,'2.5',$$What is a secure baseline audit and why repeat it?$$,$$Periodically re-comparing live configuration against the approved hardened baseline to catch drift (re-enabled services, changed settings) introduced after initial hardening.$$),
('f2-075','core',2,'2.5',$$What is threat modeling as a proactive mitigation?$$,$$Systematically identifying likely attackers, entry points, and attack paths for a system BEFORE building it, so defenses are designed in rather than bolted on after an incident.$$);
insert into public.questions (id, domain, objective, qtype, difficulty, stem, choices, answer, explanation) values
('q2-056',2,'2.1','mcq',2,$q$An employee accidentally emails a spreadsheet containing customer SSNs to the wrong recipient because they didn''t double-check the auto-complete address. What type of insider threat is this?$q$,$q$["Malicious insider","Negligent insider","Nation-state actor","Hacktivist"]$q$::jsonb,'1'::jsonb,$q$Unintentional carelessness causing exposure is a negligent insider - no intent to harm, but still a real risk requiring training and safeguards like DLP. Malicious insiders act with intent.$q$),
('q2-057',2,'2.1','mcq',2,$q$A threat actor maintains covert access inside a critical infrastructure network for over a year, carefully avoiding detection while mapping the environment. Which term best captures this behavior pattern?$q$,$q$["Script kiddie activity","Advanced Persistent Threat (APT)","Hacktivism","Shadow IT"]$q$::jsonb,'1'::jsonb,$q$Long dwell time, stealth, and patience define an APT - typically nation-state resourced. Script kiddies are noisy and unsophisticated; hacktivism seeks visibility, not stealth.$q$),
('q2-058',2,'2.1','mcq',1,$q$Which threat actor is most likely to use only publicly available tools with little customization?$q$,$q$["Nation-state","Organized crime","Unskilled attacker (script kiddie)","Insider threat"]$q$::jsonb,'2'::jsonb,$q$Unskilled attackers (script kiddies) run public, off-the-shelf tools they barely understand. Nation-states and organized crime typically field custom or purpose-built tooling.$q$),
('q2-059',2,'2.1','mcq',2,$q$A former employee, still holding valid VPN credentials because offboarding was incomplete, logs in and deletes project files out of anger over their termination. Which threat actor category and motivation apply?$q$,$q$["Insider threat; revenge","Nation-state; espionage","Hacktivist; ideology","Shadow IT; convenience"]$q$::jsonb,'0'::jsonb,$q$A former employee acting with intent to harm using retained legitimate access is an insider threat motivated by revenge - a direct consequence of incomplete deprovisioning.$q$),
('q2-060',2,'2.1','matching',2,$q$Match each threat actor to a defining resource/behavior trait.$q$,$q${"left":["Nation-state","Organized crime","Script kiddie","APT group"],"right":["Custom zero-day tooling and patience","Profit-driven with real operational infrastructure","Uses public tools with minimal customization","Long-term stealthy persistence for espionage"]}$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Nation-states field custom tooling and patience; organized crime runs profitable criminal infrastructure (ransomware ops); script kiddies use unmodified public tools; APT groups (often nation-state-aligned) persist stealthily for long-term intelligence gain.$q$),
('q2-061',2,'2.2','mcq',2,$q$A user scans a QR code taped over a legitimate one on a parking meter, landing on a fake payment site that steals their card info. What is this attack called?$q$,$q$["Vishing","Quishing","Typosquatting","Watering hole"]$q$::jsonb,'1'::jsonb,$q$QR-code-based phishing is quishing - the destination isn't visible until after scanning, hiding malicious intent until it's too late. Vishing is voice-based; typosquatting uses look-alike domains.$q$),
('q2-062',2,'2.2','mcq',3,$q$An attacker mails USB drives disguised as promotional gifts to employees; when plugged in, the device emulates a keyboard and types commands to install malware without any file being opened. What attack technique is this?$q$,$q$["Typosquatting","BadUSB (HID emulation attack)","Watering hole","Business email compromise"]$q$::jsonb,'1'::jsonb,$q$A device that impersonates a keyboard (Human Interface Device) to inject commands the instant it's connected is a BadUSB attack - no user click on a file is needed, unlike simple infected-file baiting.$q$),
('q2-063',2,'2.2','mcq',2,$q$An attacker calls pretending to be a company''s CFO, using an invented story to convince an employee to skip verification and process a wire transfer. Which persuasion principle is being exploited, and what is the invented story called?$q$,$q$["Authority; pretext","Scarcity; whaling","Urgency; typosquatting","Consensus; watering hole"]$q$::jsonb,'0'::jsonb,$q$Impersonating someone whose instructions aren't normally questioned exploits authority; the fabricated backstory justifying the request is the pretext. Whaling, typosquatting, and watering holes describe different attack mechanics, not this scenario.$q$),
('q2-064',2,'2.2','mcq',2,$q$A legitimate ad network unknowingly serves a banner ad on a trusted news site that silently redirects visitors to an exploit kit. What is this called?$q$,$q$["Malvertising","Whaling","Smishing","Domain hijacking"]$q$::jsonb,'0'::jsonb,$q$Malicious code delivered through a legitimate ad network is malvertising - it compromises visitors of otherwise trustworthy sites without ever touching the site's own code.$q$),
('q2-065',2,'2.2','mcq',2,$q$An attacker registers "rnicrosoft.com" (using "rn" to mimic "m") to host a phishing page. What technique is this specifically?$q$,$q$["A homoglyph variant of typosquatting","Watering hole attack","Business email compromise","Pharming"]$q$::jsonb,'0'::jsonb,$q$Using visually similar character combinations in a look-alike domain is a homoglyph-based form of typosquatting, designed to fool a quick visual scan of the URL.$q$),
('q2-066',2,'2.2','mcq',2,$q$Which vector describes an attacker compromising a niche industry forum that a target company's engineers are known to frequent, waiting for them to visit?$q$,$q$["Watering hole attack","Supply chain attack","Vishing","Prepending"]$q$::jsonb,'0'::jsonb,$q$Compromising a site the target GROUP is known to visit and letting them infect themselves voluntarily is a watering hole attack. Supply chain attacks come through vendors, not shared browsing habits.$q$),
('q2-067',2,'2.2','mcq',3,$q$A phishing email's subject line begins with "[EXTERNAL]" added automatically by the mail gateway, but the attacker also crafts the body to open with a fake "RE:" to look like a reply to a real thread. What social engineering technique does adding the fake "RE:" represent?$q$,$q$["Prepending","Pharming","Tailgating","Vishing"]$q$::jsonb,'0'::jsonb,$q$Prepending adds misleading text (like a fake reply marker) to a message to increase its perceived legitimacy and lower a recipient's guard. Pharming redirects DNS; tailgating and vishing are physical/voice techniques.$q$),
('q2-068',2,'2.3','mcq',1,$q$A newly deployed server is compromised through its still-active default administrator account and password. What vulnerability class is this?$q$,$q$["Zero-day","Default configuration","Race condition","Firmware vulnerability"]$q$::jsonb,'1'::jsonb,$q$Unchanged shipped credentials are a default configuration vulnerability - one of the most common and easily preventable weaknesses. It requires no unknown flaw (zero-day) or timing exploit (race condition).$q$),
('q2-069',2,'2.3','mcq',2,$q$An API endpoint returns a customer's full profile including SSN when queried, even though the calling application only needed the customer's name. What vulnerability does this represent?$q$,$q$["Insecure API - excessive data exposure","Buffer overflow","VM escape","Directory traversal"]$q$::jsonb,'0'::jsonb,$q$Returning more data than the caller needs is a classic insecure-API flaw (excessive data exposure), distinct from memory-corruption bugs or filesystem-traversal issues.$q$),
('q2-070',2,'2.3','mcq',2,$q$A development team builds container images on top of a public base image that hasn't been updated in two years and contains several known CVEs. What risk category is this?$q$,$q$["VM escape","Container image supply-chain risk","Race condition","Firmware vulnerability"]$q$::jsonb,'1'::jsonb,$q$Unscanned, stale base images inherit their known vulnerabilities into every container built from them - a supply-chain risk specific to container workflows, addressed by image scanning and trusted registries.$q$),
('q2-071',2,'2.3','mcq',3,$q$A privileged process checks a file's permissions, then a moment later an attacker swaps that file for a symlink pointing to /etc/shadow before the process opens it. What specific exploitation technique is this?$q$,$q$["Buffer overflow","TOCTOU symlink attack","SQL injection","Memory injection"]$q$::jsonb,'1'::jsonb,$q$The gap between the permission CHECK and the actual file USE is a time-of-check to time-of-use race condition, exploited here via a symlink swap. This differs from memory corruption, injection, or in-process code insertion.$q$),
('q2-072',2,'2.3','mcq',2,$q$A company's cloud storage bucket is discovered to have "public read" access enabled by mistake since deployment. Which vulnerability category applies?$q$,$q$["Zero-day","Cloud misconfiguration","Legacy system vulnerability","Mobile vulnerability"]$q$::jsonb,'1'::jsonb,$q$The platform functioned exactly as configured; the CONFIGURATION was wrong - the textbook cloud misconfiguration. No unknown flaw, obsolete system, or mobile-specific issue is involved.$q$),
('q2-073',2,'2.3','mcq',2,$q$Which of these is the BEST example of an insecure protocol creating a vulnerability?$q$,$q$["Using SNMPv3 for device management","Using Telnet to manage network switches","Using HTTPS for a login page","Using SSH for remote administration"]$q$::jsonb,'1'::jsonb,$q$Telnet transmits credentials and session data in cleartext - a textbook insecure-protocol vulnerability. SNMPv3, HTTPS, and SSH are each the secure alternative to a legacy cleartext protocol.$q$),
('q2-074',2,'2.3','mcq',2,$q$Why do end-of-life industrial control systems remain vulnerable indefinitely once support ends?$q$,$q$["They automatically upgrade themselves","No vendor patches will ever be released for newly discovered flaws, so exposure only grows over time","ICS devices cannot be attacked","They are immune due to isolation"]$q$::jsonb,'1'::jsonb,$q$Once a vendor stops support, every newly discovered flaw remains permanently unpatched - only isolation, monitoring, or replacement reduce the growing risk. Isolation helps but doesn't grant automatic immunity.$q$),
('q2-075',2,'2.4','mcq',2,$q$Malware changes its encryption wrapper every time it infects a new host, but the underlying malicious payload logic stays identical. What is this malware behavior called?$q$,$q$["Metamorphic","Polymorphic","Fileless","Rootkit-based"]$q$::jsonb,'1'::jsonb,$q$Polymorphic malware changes its outward appearance (encryption/obfuscation) each infection while the core code is unchanged. Metamorphic malware goes further and rewrites the actual code logic each time - a harder-to-detect evolution of the same idea.$q$),
('q2-076',2,'2.4','mcq',1,$q$Thousands of compromised IoT devices are simultaneously directed to flood a target with traffic. What best describes this attacker infrastructure?$q$,$q$["A worm","A botnet","A rootkit","A logic bomb"]$q$::jsonb,'1'::jsonb,$q$A large network of compromised, remotely controlled hosts under one attacker's C2 is a botnet, commonly weaponized for DDoS. A worm is self-propagating malware, not the resulting infrastructure.$q$),
('q2-077',2,'2.4','mcq',2,$q$An attacker obtains a Windows password hash from a compromised machine and uses it directly to authenticate to another server on the network, without ever cracking it to plaintext. What attack is this?$q$,$q$["Password spraying","Pass-the-hash","Rainbow table attack","Credential stuffing"]$q$::jsonb,'1'::jsonb,$q$Reusing the captured hash itself as proof of authentication - supported by protocols like NTLM - is pass-the-hash; no cracking to plaintext is required. Rainbow tables are used to CRACK hashes offline, the opposite approach.$q$),
('q2-078',2,'2.4','mcq',2,$q$An attacker sends forged ARP replies claiming their MAC address belongs to the network's default gateway. What is the immediate effect?$q$,$q$["Every host on the switch reboots","Victims send their gateway-bound traffic to the attacker instead, enabling interception","The DNS server is poisoned","The DHCP server stops leasing addresses"]$q$::jsonb,'1'::jsonb,$q$This is ARP spoofing/poisoning - the mechanism behind on-path attacks on a local network, redirecting traffic to the attacker. It doesn't directly touch DNS resolution or DHCP leasing.$q$),
('q2-079',2,'2.4','mcq',2,$q$Attackers harvest thousands of credentials from a breached retailer and, months later, try that exact same username/password list against a completely unrelated banking site. What attack is this?$q$,$q$["Password spraying","Credential stuffing","Brute force","Rainbow table attack"]$q$::jsonb,'1'::jsonb,$q$Replaying breached username/password PAIRS against a different service, banking on password reuse, is credential stuffing. Spraying tries one password against many accounts; brute force guesses systematically against one account.$q$),
('q2-080',2,'2.4','mcq',2,$q$A server's fans run at full speed constantly, its CPU shows sustained 95%+ usage with no scheduled job explaining it, and the cloud bill spikes. What is the MOST likely cause?$q$,$q$["A logic bomb","Cryptomining malware abusing compute resources","A directory traversal attack","An expired certificate"]$q$::jsonb,'1'::jsonb,$q$Sustained abnormal resource consumption with no legitimate workload, plus cost spikes, is the classic cryptojacking/cryptomining malware indicator. Logic bombs sit dormant until triggered; certificates and traversal attacks don't drive CPU load.$q$),
('q2-081',2,'2.4','mcq',3,$q$A SOC analyst notices a host repeatedly resolving dozens of unique, long, random-looking subdomains of the same external domain every few seconds, alongside abnormal outbound data volume. What should the analyst suspect?$q$,$q$["Normal CDN caching","DNS tunneling exfiltration","A software update check","A misconfigured printer"]$q$::jsonb,'1'::jsonb,$q$High-volume, unique-subdomain DNS queries to one domain, paired with unusual outbound volume, is the signature of DNS tunneling - data smuggled through a protocol firewalls rarely block closely.$q$),
('q2-082',2,'2.4','ordering',3,$q$Order the stages of a typical credential-based intrusion, from initial theft to impact.$q$,$q$["Attacker harvests credentials via phishing","Attacker validates the credentials against the target service","Attacker authenticates and escalates privileges","Attacker exfiltrates or damages data"]$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$The natural progression: obtain credentials, confirm they work, use them to gain and escalate access, then act on objectives such as exfiltration. Interrupting any earlier stage prevents the later ones.$q$),
('q2-083',2,'2.4','mcq',2,$q$Which indicator would MOST strongly suggest a distributed brute-force/credential-stuffing campaign rather than a single attacker guessing one account?$q$,$q$["A single IP address failing login attempts on one account repeatedly","Login attempts against many different accounts arriving from thousands of distinct IP addresses in a short window","One successful login from the user's usual location","A single failed login followed by a successful one from the same device"]$q$::jsonb,'1'::jsonb,$q$A wide spread of source IPs and target accounts hitting the login endpoint simultaneously is the signature of a distributed, often botnet-driven automated campaign - very different from one attacker manually guessing.$q$),
('q2-084',2,'2.4','mcq',2,$q$Malware disables the victim's antivirus and hides its own process from Task Manager by hooking low-level OS functions. What malware category best fits this behavior?$q$,$q$["Trojan","Rootkit","Adware","Worm"]$q$::jsonb,'1'::jsonb,$q$Concealing itself and other malicious activity from standard OS-level visibility, often via kernel/API hooking, is the defining rootkit behavior. A trojan is about disguised delivery, not concealment technique.$q$),
('q2-085',2,'2.5','mcq',2,$q$A company restricts administrative logins to only occur between 8 AM and 6 PM local time. What mitigation category is this?$q$,$q$["Encryption","Time-based access restriction","Network segmentation","Least privilege"]$q$::jsonb,'1'::jsonb,$q$Limiting WHEN an account can authenticate is a time-based access restriction, shrinking the window a stolen credential can be used undetected outside business hours.$q$),
('q2-086',2,'2.5','mcq',2,$q$Six months after initial hardening, an audit finds several servers now have re-enabled remote management services that were originally disabled. What practice would have caught this earlier?$q$,$q$["A one-time penetration test","Periodic secure baseline auditing for configuration drift","Disabling logging","Removing the firewall"]$q$::jsonb,'1'::jsonb,$q$Hardening is a snapshot; configuration drift creeps back in over time, so recurring baseline audits - not a single point-in-time test - are needed to catch it continuously.$q$),
('q2-087',2,'2.5','mcq',3,$q$Before writing a single line of code for a new payment feature, the team maps out likely attackers, entry points, and abuse cases to decide what controls the design needs. What activity is this?$q$,$q$["Penetration testing","Threat modeling","Vulnerability scanning","Root cause analysis"]$q$::jsonb,'1'::jsonb,$q$Threat modeling happens proactively during design, before the system exists to test against - unlike pen testing or scanning, which assess something already built.$q$),
('q2-088',2,'2.5','mcq',2,$q$Which mitigation most directly reduces the blast radius if a single web server in a three-tier architecture is compromised?$q$,$q$["Longer passwords on the database","Network segmentation isolating the web, app, and database tiers","More frequent backups","Disabling the firewall for troubleshooting"]$q$::jsonb,'1'::jsonb,$q$Segmenting tiers so a compromised web server cannot directly reach the database tier limits lateral movement and contains the blast radius. Backups aid recovery but don't prevent spread.$q$),
('q2-089',2,'2.5','mcq',2,$q$Why is disabling unused services considered both a hardening AND a mitigation technique?$q$,$q$["It has no security benefit","Fewer running services means fewer exploitable entry points, shrinking the attack surface before AND after deployment","It only affects performance, not security","It is required only for compliance paperwork"]$q$::jsonb,'1'::jsonb,$q$Every running service is a potential entry point; removing unneeded ones shrinks the attack surface both at initial hardening and as an ongoing mitigation against newly discovered flaws in services you never needed.$q$),
('q2-090',2,'2.4','mcq',2,$q$A user's antivirus quarantines a file, but three days later the same malware reappears after every reboot despite the AV showing "clean." Which persistence mechanism is MOST likely?$q$,$q$["A registry run key or scheduled task re-launching a dropper the AV didn't catch","A firewall misconfiguration","A hardware failure","A DNS misconfiguration"]$q$::jsonb,'0'::jsonb,$q$Persistence via autorun registry keys or scheduled tasks re-installs or re-launches malware after reboot even if one component was cleaned - full removal requires finding and eliminating the persistence mechanism itself, not just the payload.$q$),
('q2-091',2,'2.1','mcq',2,$q$A disgruntled systems administrator, about to be laid off, quietly copies the customer database to a personal cloud drive before their access is revoked. What combination of threat actor and motivation applies?$q$,$q$["Insider threat; revenge/financial gain","Hacktivist; ideology","Nation-state; espionage","Shadow IT; convenience"]$q$::jsonb,'0'::jsonb,$q$A trusted employee weaponizing legitimate access before losing it, driven by resentment and potential profit, is an insider threat motivated by revenge/financial gain - not an external or ideological actor.$q$),
('q2-092',2,'2.2','mcq',2,$q$An attacker impersonates a company's IT helpdesk in a phone call, asking an employee to "verify their password" to fix a fake ticket. What social engineering technique is this?$q$,$q$["Vishing (voice phishing) using impersonation and pretexting","Quishing","Watering hole","Typosquatting"]$q$::jsonb,'0'::jsonb,$q$A phone-based social engineering attempt combining impersonation (posing as IT) and pretexting (the fake ticket) is vishing. Quishing is QR-based, watering holes and typosquatting are website-based vectors.$q$),
('q2-093',2,'2.3','mcq',2,$q$A mobile banking app is found to store the user's session token in plaintext in an unencrypted local file accessible to other apps on a rooted device. What vulnerability class is this?$q$,$q$["Insecure storage on mobile devices","VM escape","Firmware vulnerability","DNS poisoning"]$q$::jsonb,'0'::jsonb,$q$Storing sensitive tokens in plaintext, readable by other apps on a compromised (rooted) device, is an insecure-storage mobile vulnerability - unrelated to hypervisor escape, firmware, or DNS issues.$q$),
('q2-094',2,'2.5','mcq',2,$q$An organization requires that no single administrator can both approve AND execute a wire transfer. What mitigation principle does this reflect?$q$,$q$["Least privilege","Separation of duties","Defense in depth","Threat modeling"]$q$::jsonb,'1'::jsonb,$q$Splitting a sensitive process so no one person can both authorize and carry it out is separation of duties, preventing unilateral fraud - distinct from least privilege, which limits an individual's rights rather than restructuring a workflow.$q$),
('q2-095',2,'2.4','mcq',3,$q$A workstation shows a spike in failed logon events, immediately followed by a successful logon on the same account, followed within seconds by that account creating a new local administrator account. What does this sequence MOST likely represent?$q$,$q$["A user who forgot their password and got IT help","Successful credential guessing/brute force followed by privilege escalation","A routine software update","A printer driver installation"]$q$::jsonb,'1'::jsonb,$q$Failed logons succeeding right before privilege-escalation activity (new admin account creation) is a strong compromise signature: guessing that worked, immediately leveraged to gain persistence and elevated access.$q$);
